Method.Source:
[   
    DataMemberAttribute('ProdId'),
    SysOperationLabelAttribute(literalstr("@NDX:NXAReportFinishedBasketProdId")),
    SysOperationDisplayOrderAttribute('1')
]
public ProdId parmProdId(ProdId _parmValue = contractProdId)
{
    contractProdId = _parmValue;

    return contractProdId;
}

[
    DataMemberAttribute('ItemId'),
    SysOperationDisplayOrderAttribute('2')
]
public itemid parmItemId(ItemId _parmValue = contractItemId)
{
    contractItemId = _parmValue;

    return contractItemId;
}

[
    DataMemberAttribute('Qty'),
    SysOperationDisplayOrderAttribute('3')
]
public Qty parmQty(qty _parmValue = contractQty)
{
    contractQty = _parmValue;

    return contractQty;
}
